package main

import (
	"fmt"

	"aiharness"
)

func main() {
	fmt.Println("Initializing OmniMonitor with central Jev harness...")
	tools := []string{"filesystem", "sqlite", "docker", "github", "puppeteer", "mempalace"}

	result, status, err := aiharness.QueryJev(
		"We need to initialize the project directory and verify local storage health.", tools)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Printf("Jev status: %d\nResponse: %s\n", status, result)
}
